INSERT IGNORE INTO shops (id, name, category, area, address, description, rating, reviews_count, image, phone, timing) VALUES
  ('shop-1', 'Malabar Heritage Spices & Pantry', 'Groceries', 'Koppikar Road', 'Koppikar Road Market, Near Durgadbail, Hubballi - 580020', 'Specialty family-owned grocer sourcing single-origin spices, cold-pressed oils, and traditional grains directly from southern farms.', 4.8, 142, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=600&q=80', '+91 98451 22345', '8:30 AM - 9:00 PM'),
  ('shop-2', 'Apex Tech & Gadget Hub', 'Electronics', 'Vidyanagar', 'Opp. KLE Tech University, Vidyanagar, Hubballi - 580021', 'Trusted neighbourhood electronics store offering warranty-backed tech accessories, audio gear, cables, and smart home essentials.', 4.7, 98, 'https://images.unsplash.com/photo-1550009158-9ebf69173e03?auto=format&fit=crop&w=600&q=80', '+91 98802 33411', '10:00 AM - 9:30 PM'),
  ('shop-3', 'Vogue Craft & Handloom Studio', 'Fashion', 'Koppikar Road', 'Near Cotton Market, Koppikar Road, Hubballi - 580020', 'Boutique studio celebrating Karnataka and South Indian handloom weaves, pure cotton everyday wear, and eco-conscious canvas totes.', 4.9, 76, 'https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?auto=format&fit=crop&w=600&q=80', '+91 97412 88902', '10:30 AM - 8:30 PM'),
  ('shop-4', 'Saraswati Book Haven & Fine Papers', 'Books & Stationery', 'Keshwapur', 'Kusugal Road, Keshwapur, Hubballi - 580023', 'Iconic independent bookstore carrying Indian literature, academic titles, vintage fountain pen inks, and handmade cotton journals.', 4.9, 210, 'https://images.unsplash.com/photo-1507842229450-79779f62a6b2?auto=format&fit=crop&w=600&q=80', '+91 98440 11988', '9:30 AM - 8:30 PM'),
  ('shop-5', 'Prakriti Home & Sustainable Living', 'Home & Living', 'Shirur Park', 'Shirur Park 2nd Cross, Vidyanagar, Hubballi - 580021', 'Conscious home lifestyle store curating artisanal terracotta planters, brass decor, soy wax aromatherapy candles, and handwoven mats.', 4.6, 65, 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=600&q=80', '+91 99003 44521', '10:00 AM - 8:00 PM'),
  ('shop-6', 'Veda Botanics & Apothecary', 'Personal Care', 'Gokul Road', 'Near Airport Bypass, Gokul Road, Hubballi - 580030', 'Clean personal care apothecary formulating small-batch herbal soaps, pure floral hydrosols, and therapeutic scalp elixirs.', 4.8, 114, 'https://images.unsplash.com/photo-1608248597359-54848378216c?auto=format&fit=crop&w=600&q=80', '+91 96118 77203', '10:00 AM - 9:00 PM'),
  ('shop-7', 'DecaPulse Sports & Outdoor Hub', 'Sports & Lifestyle', 'Unkal', 'Unkal Lake Promenade, PB Road, Hubballi - 580031', 'Community sports outfitter stocking badminton rackets, shuttlecocks, running gear, and yoga accessories for local athletes.', 4.8, 89, 'https://images.unsplash.com/photo-1517649763962-0c623266ddc0?auto=format&fit=crop&w=600&q=80', '+91 98860 45678', '9:00 AM - 9:00 PM');
INSERT IGNORE INTO products (id, name, category, shop_id, price, stock, rating, reviews_count, description, attributes, tags, image, is_featured) VALUES
  ('prod-101', 'Wayanad Cardamom Pods (Grade 8mm)', 'Groceries', 'shop-1', 340, 18, 4.9, 38, 'Sun-dried jumbo green cardamom pods sourced from Wayanad estates. Intensely aromatic, ideal for traditional desserts, biryanis, and spiced chai.', '{"Net Weight":"100g","Origin":"Wayanad, Kerala","Shelf Life":"12 Months","Processing":"Hand-picked, sun dried"}', '["spices","organic","chai","aromatic"]', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-102', 'Cold-Pressed Sesame Oil (Wood Churned)', 'Groceries', 'shop-1', 290, 12, 4.7, 24, 'Traditional wood-pressed (marachekku) sesame oil extracted at room temperature with palm jaggery. Rich in antioxidants and healthy fatty acids.', '{"Volume":"500ml","Extraction":"Cold Wood Churned","Shelf Life":"9 Months","Preservatives":"Zero additives"}', '["oil","cooking","healthy","traditional"]', 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-103', 'Organic Tellicherry Black Peppercorns', 'Groceries', 'shop-1', 195, 22, 4.8, 19, 'World-renowned Tellicherry extra bold black pepper. Offers warm pungency and complex citrus notes when freshly cracked over dishes.', '{"Net Weight":"150g","Grade":"TGSEB Extra Bold","Origin":"Thalassery, Kerala","Harvest":"Late Season"}', '["spices","pepper","cooking"]', 'https://images.unsplash.com/photo-1599940824399-b87987ceb72a?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-104', 'Raw Coorg Forest Wild Honey', 'Groceries', 'shop-1', 450, 3, 4.9, 52, 'Unprocessed, multi-floral raw honey collected by tribal cooperatives in the Western Ghats forests. Naturally crystallized and unheated.', '{"Net Weight":"400g","Origin":"Coorg, Karnataka","Purity":"100% Raw Unpasteurized","FSSAI Certified":"Yes"}', '["honey","organic","sweetener","immunity"]', 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-105', 'Handcrafted Filter Coffee Blend (80:20)', 'Groceries', 'shop-1', 240, 0, 4.9, 67, 'Freshly roasted Chikmagalur Arabica and Robusta beans blended with 20% high-grade chicory for that authentic South Indian decoction aroma.', '{"Net Weight":"250g","Roast Level":"Dark Roast","Bean Origin":"Chikmagalur","Blend":"80% Coffee, 20% Chicory"}', '["coffee","filter coffee","beverages","chikmagalur"]', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-201', 'BoltStream 65W GaN Fast Wall Charger', 'Electronics', 'shop-2', 1899, 14, 4.8, 43, 'Ultra-compact Gallium Nitride dual Type-C and USB-A wall charger capable of powering laptops, tablets, and flagship smartphones at peak speed.', '{"Power Output":"65W Max","Ports":"2x USB-C, 1x USB-A","Technology":"GaN III","Warranty":"1 Year Seller Replacement"}', '["charger","usb-c","laptop","gan"]', 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-202', 'AcousticPure Wireless Earbuds (ANC)', 'Electronics', 'shop-2', 2799, 8, 4.6, 31, 'Active Noise Cancellation true wireless earbuds featuring 10mm titanium drivers, 32-hour playback battery case, and IPX5 splash resistance.', '{"Driver Size":"10mm Dynamic","Battery Life":"32 Hours Total","Noise Control":"Hybrid ANC 28dB","Connectivity":"Bluetooth 5.3"}', '["audio","earbuds","wireless","anc"]', 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-203', 'Braided 2M Type-C to Type-C 100W Cable', 'Electronics', 'shop-2', 499, 25, 4.5, 18, 'Heavy-duty Kevlar-reinforced braided cable certified for Power Delivery 3.0 up to 100W with reinforced strain relief collars.', '{"Length":"2 Metres","Power Delivery":"100W (20V/5A)","Data Speed":"480 Mbps","Jacket":"Nylon Braided"}', '["cable","usb-c","charging","accessories"]', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-204', 'Smart RGB Desk Ambient Light Bar', 'Electronics', 'shop-2', 1450, 2, 4.7, 15, 'Monitor-mounted or desk-standing smart light bar with sound-reactive music syncing and customizable warm-to-cool workspace illumination.', '{"Lighting":"16M RGB + 2700K-6500K CCT","Input":"USB 5V/2A","Control":"Touch + App","Mounting":"Weighted Base"}', '["lighting","smart home","desk setup","gadget"]', 'https://images.unsplash.com/photo-1507499739999-097706ad8914?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-205', 'Precision Aluminum Laptop Riser Stand', 'Electronics', 'shop-2', 1199, 9, 4.8, 27, 'Ergonomic CNC-machined sandblasted aluminum stand supporting laptops up to 16 inches. Improves airflow and posture during work hours.', '{"Material":"Anodized Aluminum Alloy","Compatibility":"11 to 16 inch laptops","Weight":"420g","Foldable":"Yes"}', '["laptop stand","ergonomics","work from home"]', 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-301', 'Handspun Khadi Cotton Mandarin Kurta', 'Fashion', 'shop-3', 1290, 7, 4.9, 41, 'Breathable, hand-spun and hand-woven pure khadi cotton shirt kurta in indigo weave. Features wooden buttons and side welt pockets.', '{"Fabric":"100% Handloom Khadi Cotton","Fit":"Relaxed Comfort Fit","Wash Care":"Gentle Hand Wash","Dye":"Natural Indigo"}', '["khadi","handloom","apparel","cotton","sustainable"]', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-302', 'Handmade Canvas & Jute Everyday Tote', 'Fashion', 'shop-3', 650, 16, 4.7, 22, 'Spacious heavy-gauge unbleached canvas tote with vegetable-tanned leather handles and an internal zip pocket for daily essentials.', '{"Material":"14oz Cotton Canvas + Leather handles","Dimensions":"38cm x 35cm x 10cm","Closure":"Magnetic snap","Capacity":"15 Litres"}', '["tote bag","canvas","eco friendly","accessories"]', 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-303', 'Kalamkari Handblock Print Dupatta', 'Fashion', 'shop-3', 890, 2, 4.8, 16, 'Authentic Machilipatnam Kalamkari printed soft Chanderi silk-cotton scarf with heritage floral creepers and hand-knotted tassels.', '{"Fabric":"Chanderi Cotton Silk","Craft":"Kalamkari Wooden Block Print","Length":"2.4 Metres","Dyes":"Vegetable derived"}', '["kalamkari","dupatta","traditional","artisan"]', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-304', 'Genuine Leather Minimalist Bifold Wallet', 'Fashion', 'shop-3', 990, 11, 4.6, 19, 'Slim hand-stitched full-grain crazy horse leather wallet with RFID blocking lining, 6 card slots, and an easy-access currency sleeve.', '{"Material":"Full-Grain Vegetable Tanned Leather","Card Capacity":"8-10 Cards","RFID Blocking":"Yes","Finish":"Vintage Tan"}', '["wallet","leather","accessories","gift"]', 'https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-401', 'Hardbound Handmade Cotton Paper Journal (A5)', 'Books & Stationery', 'shop-4', 450, 20, 4.9, 35, 'Artisanal blank journal crafted with deckle-edge 120 GSM recycled cotton rag paper, hand-bound in book-cloth with satin ribbon marker.', '{"Pages":"160 Pages (80 Sheets)","Paper Weight":"120 GSM Deckle Edge","Binding":"Smyth Sewn Hardcover","Ink Compatibility":"Fountain Pen Friendly"}', '["journal","stationery","handmade paper","writing"]', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-402', 'Sulekha Archival Fountain Pen Ink (Black - 60ml)', 'Books & Stationery', 'shop-4', 320, 15, 4.8, 29, 'Legendary Indian heritage fountain pen ink with neutral pH and deep archival saturation. Smooth flow without feathering on quality paper.', '{"Volume":"60ml Glass Bottle","Color":"Swadeshi Midnight Black","pH":"Neutral 7.0","Water Resistance":"Moderate"}', '["ink","fountain pen","calligraphy","heritage"]', 'https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-403', 'Bangalore: A History of an Indian Metropolis', 'Books & Stationery', 'shop-4', 599, 5, 4.9, 44, 'Richly documented historical exploration of Bengaluru from Kempe Gowda’s mud fort, colonial cantonment to modern tech capital.', '{"Author":"Dr. K. Srinivas","Format":"Paperback, 368 Pages","Publisher":"Heritage Press","Language":"English"}', '["books","history","bangalore","reading"]', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-404', 'Solid Brass Hexagonal Pocket Pen', 'Books & Stationery', 'shop-4', 1350, 3, 4.8, 17, 'Heavyweight machined solid brass pocket pen that develops a unique natural patina over time. Uses standard Schmidt rollerball refills.', '{"Body":"Solid Raw Machined Brass","Length":"105mm (closed), 138mm (posted)","Weight":"54g","Refill":"Schmidt P900 / Parker style"}', '["pen","brass","everyday carry","luxury"]', 'https://images.unsplash.com/photo-1585336261026-633036a9b407?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-501', 'Handcrafted Terracotta Indoor Planter (7 Inch)', 'Home & Living', 'shop-5', 380, 14, 4.7, 23, 'Porous unglazed terracotta planter wheel-thrown by Ramanagara artisans. Promotes natural root aeration and includes matching drainage saucer.', '{"Diameter":"7 Inches (18cm)","Material":"Natural Kiln-Fired Clay","Drainage Hole":"Yes with saucer","Craft":"Potters Guild Karnataka"}', '["plants","terracotta","decor","gardening"]', 'https://images.unsplash.com/photo-1485955900006-10f4d324d411?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-502', 'Sandalwood & Cardamom Soy Wax Candle', 'Home & Living', 'shop-5', 520, 19, 4.9, 37, 'Clean-burning 100% natural soy wax candle hand-poured in a reusable amber glass jar. Scented with Mysore sandalwood and green cardamom essential oils.', '{"Wax":"Pure Soy Wax","Burn Time":"40+ Hours","Wick":"Lead-free Cotton Wick","Weight":"220g Net"}', '["candle","aromatherapy","home decor","sandalwood"]', 'https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-503', 'Hand-Hammered Pure Copper Water Bottle (950ml)', 'Home & Living', 'shop-5', 890, 6, 4.8, 49, 'Traditional Ayurvedic copper vessel with diamond hammered texture for better grip and leakproof silicone ring seal.', '{"Capacity":"950ml","Material":"99.2% Pure Certified Copper","Finish":"Hand Hammered","Weight":"290g"}', '["copper","wellness","water bottle","ayurveda"]', 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-504', 'Traditional Brass Diya Oil Lamp (Set of 2)', 'Home & Living', 'shop-5', 680, 0, 4.6, 18, 'Cast solid brass tabletop diyas with ornate peacock finial. Perfect for daily festive rituals and serene ambient evening light.', '{"Material":"Heavy Cast Brass","Set Includes":"2 Matching Lamps","Height":"12cm Each","Weight":"480g Total"}', '["brass","puja","lamp","festive"]', 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-601', 'Neem & Tulsi Cold-Processed Bathing Bar', 'Personal Care', 'shop-6', 180, 24, 4.9, 58, 'Gentle clarifying cold-process soap made with raw neem leaf paste, wild holy basil, coconut oil, and nourishing kokum butter.', '{"Weight":"125g Bar","Key Botanicals":"Wild Neem & Holy Tulsi","Skin Type":"All skin types / acne prone","Free From":"SLS, Parabens, Palm Oil"}', '["soap","ayurvedic","skincare","natural"]', 'https://images.unsplash.com/photo-1607006314591-628d6896200d?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-602', 'Bhringraj & Brahmi Herbal Scalp Oil', 'Personal Care', 'shop-6', 490, 9, 4.8, 33, 'Slow-infused Ayurvedic hair tonic prepared via taila paka vidhi using organic sesame base, bhringraj herb, amla, and hibiscus blossoms.', '{"Volume":"150ml Glass Pump","Method":"Traditional Kshira Paka Infusion","Application":"Root massage twice weekly","Fragrance":"100% Botanical herbs"}', '["haircare","oil","ayurveda","organic"]', 'https://images.unsplash.com/photo-1608248597359-54848378216c?auto=format&fit=crop&w=600&q=80', 0),
  ('prod-603', 'Steam-Distilled Kannauj Rose Hydrosol Mist', 'Personal Care', 'shop-6', 360, 2, 4.9, 42, 'Pure copper-still distilled hydrosol of Kannauj Damask roses. Instantly tones, calms redness, and hydrates tired skin throughout the day.', '{"Volume":"100ml Fine Mist Spray","Botanical":"Rosa Damascena","Alcohol Content":"0% Alcohol Free","Distillation":"First steam distillate"}', '["rose water","toner","facial mist","organic"]', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', 1),
  ('prod-604', 'Kokum Butter & Mint Nourishing Lip Butter', 'Personal Care', 'shop-6', 195, 17, 4.7, 26, 'Ultra-moisturizing lip balm in an eco-friendly slide tin. Blended with wild kokum butter, cold-pressed almond oil, and refreshing spearmint.', '{"Net Weight":"15g Slide Tin","Base":"Unrefined Kokum & Beeswax","Flavour":"Subtle Field Mint","Packaging":"100% Recyclable Aluminium"}', '["lip balm","kokum","natural","moisturizer"]', 'https://images.unsplash.com/photo-1599305090598-fe179d501227?auto=format&fit=crop&w=600&q=80', 0);
